ired"},"429":{"content":{"application/problem+json":{"examples":{"tooManyRequests":{"value":{"instance":"urn:uuid:3b1f0e6a-9c2d-4f57-8a41-0d5e2c7b9f10","status":429,"title":"Too Many Requests"}}},"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"Too many requests from this client; retry after Retry-After seconds","headers":{"Retry-After":{"description":"Whole seconds until this client's next request is admitted","schema":{"type":"integer","format":"int32","minimum":1}}}}},"summary":"Open a short link","tags":["redirect-controller"]}}},"components":{"schemas":{"AuditEntry":{"type":"object","properties":{"action":{"type":"string","description":"What happened","example":"link.retire"},"actor":{"type":"string","description":"Who acted","example":"anonymous"},"after":{"type":"object","description":"The state after the change, as stored"},"before":{"type":["object","null"],"description":"The state before the change, as stored; null for a create"},"entity":{"type":"string","description":"The kind of thing changed","example":"link"},"entityId":{"type":"string","description":"The public identifier of the thing changed","example":"jHkOIMpK"},"occurredAt":{"type":"string","format":"date-time","description":"When the mutation happened (UTC)","example":"2026-10-03T17:29:41.033Z"},"requestId":{"type":"string","description":"The X-Request-Id of the request that made the change"}}},"AuditPage":{"type":"object","properties":{"items":{"type":"array","items":{"$ref":"#/components/schemas/AuditEntry"}},"next":{"type":["string","null"],"description":"Pass back as cursor for the next page; null on the last page"}}},"CreateLinkRequest":{"type":"object","properties":{"url":{"type":"string"}}},"DayClicks":{"type":"object","properties":{"clicks":{"type":"integer","format":"int64"},"date":{"type":"string","format":"date"}}},"LinkResponse":{"type":"object","properties":{"code":{"type":"string"},"createdAt":{"type":"string","format":"date-time"},"shortUrl":{"type":"string"